import React from 'react';
import ReactDOM from 'react-dom';
import './index.css';
import * as serviceWorker from './serviceWorker';
import { Provider } from 'react-redux';
import { configureApi, req, useApiGet, useApiLoading } from './api';

const c = {
  FOO1: 'CONSTANT_1',
  FOO2: 'CONSTANT_2',
  FOO3: 'CONSTANT_3',
  FOO1_INIT_VALUE: [],
  FOO2_INIT_VALUE: [],
  FOO3_INIT_VALUE: [],
}

export const store = configureApi({
  endpoint: 'http://localhost:8000',
  defaultValue: {
    [c.FOO1]: c.FOO1_INIT_VALUE,
    [c.FOO2]: c.FOO2_INIT_VALUE,
    [c.FOO3]: c.FOO3_INIT_VALUE,
  },
  // cacheStorage: 'INDEXEDDB',
});

const wait = t => new Promise(r => setTimeout(r, t));

const App = () => {
  const [counter, setCounter] = React.useState(0);
  const init = async () => {
    console.log('call this');
    req.get({
      key: 'LOAD_THIS',
      url: () => 'https://coronavirus-tracker-api.herokuapp.com/v2/locations',
      params: { q: 1 },
      transform: (res) => {
        console.log('response', res);
        return res;
      },
      cacheKey: 'asda',
      cache: true,
    });
    await wait(200);
    req.get({
      key: 'LOAD_THIS',
      url: () => 'https://coronavirus-tracker-api.herokuapp.com/v2/locations',
      params: { q: 2 },
      transform: (res) => {
        console.log('response', res);
        return res;
      },
      cacheKey: 'asda',
      cache: true,
    });
  }
  React.useEffect(() => {
    init();
  }, []);
  const a = useApiGet('FOO', {});
  React.useEffect(() => {
    console.log('changed!', a);
  }, [a]);
  const handlePatch = () => {
    req.patch({
      key: 'PATCH',
      url: () => 'http://localhost:3000/patch',
      payload: {
        hello: 'world',
      },
    });
  }
  const isPatching = useApiLoading('PATCH', 'patch');
  return (
    <div>
      <button type="button" onClick={handlePatch} disabled={isPatching}>Sample Patch</button>
      <hr />
      SAMPLE THISS
      <button onClick={() => setCounter(counter + 1)} type="button">{counter}</button>
      <button onClick={() => {
        req.clearCache();
      }} type="button">CLEAR CACHE</button>
    </div>
  )
};

ReactDOM.render(
  <Provider store={store}>
    <App />
  </Provider>
, document.getElementById('root'));

serviceWorker.unregister();

